  "mb_credit": "Produkt <a href=\"https://nunex-mbrothers.github.io/mBrothers/\" target=\"_blank\" rel=\"noopener\">mBrothers</a><span class=\"sep\" aria-hidden=\"true\"></span>developing practical solutions for small planetary systems",
  "nav_vault": "Sejf",
  "sh_label": "Szybki rzut oka",
  "sh_v2_kind": "Menedżer plików",
  "sh_v2_tag": "Już dostępny",
  "sh_v2_h": "ExplorerFocus<span class=\"v2-num\">2</span>",
  "sh_v2_sub": "Teraz z <strong>sejfami na dane</strong>",
  "sh_v2_a": "Zaszyfrowane, a otwierają się jak zwykły dysk",
  "sh_v2_b": "Czytaj i oglądaj w środku, bez odszyfrowywania wszystkiego",
  "sh_v2_go": "Dowiedz się więcej →",
  "wn_vault": "🔒 Sejfy",
  "vt_num": "§ 02 · Sejf",
  "vt_title": "Zaszyfrowany, a wciąż to tylko <em>foldery</em>.",
  "vt_blurb": "Sejf to zestaw zaszyfrowanych plików na dysku — nazwy plików, nazwy folderów i zawartość, wszystko. Otwórz go hasłem, a drzewo, podgląd, wyszukiwanie i operacje na plikach działają dokładnie tak jak zawsze, na zawartości odszyfrowywanej w locie. Zamknij go, a na dysku zostają <strong>nieczytelne nazwy i bajty bez znaczenia</strong>.",
  "vt_fed_ic": "JEDEN ALBO TYSIĄC",
  "vt_fed_h": "Sejfy to obiekty",
  "vt_fed": "Sejf to gałąź jak każda inna — umieść jeden na dysku albo sto, obok zwykłych folderów. Każdy ma własne hasło. Jeden gest otwiera wszystkie, które je dzielą, czy to jeden, czy tysiąc, i jeden gest zamyka je wszystkie.",
  "vt_seed_ic": "48 SŁÓW",
  "vt_seed_h": "Jedyna inna droga do środka",
  "vt_seed": "Każdy sejf przy tworzeniu generuje własne 48 słów — swój klucz, zapisany zwykłym językiem. Hasło albo te słowa: nic innego nie otworzy sejfu. My też nie potrafimy — stracisz oba, a sejfu już nie ma. Trzymaj słowa tam, gdzie nie ma sejfu.",
  "vt_letter_ic": "LITERA DYSKU",
  "vt_letter_h": "Otwarty dla każdej aplikacji",
  "vt_letter": "Nadaj sejfowi literę dysku, a stanie się zwykłym dyskiem dla wszystkiego, co działa na komputerze — ffmpeg, Word, WinRAR i własny rejestrator eksploratora zapisują prosto do niego. Montowanie wymienia poufność na zgodność i dlatego nigdy nie jest domyślne.",
  "vt_blocks_ic": "BEZ CZEKANIA",
  "vt_blocks_h": "Czytaj i odtwarzaj w środku",
  "vt_blocks": "Pliki są szyfrowane blokami, a nie w całości. Wideo o rozmiarze 4 GB nigdy nie musi być najpierw odszyfrowane do pamięci — podgląd się otwiera i można przeskoczyć prosto do czterdziestej minuty. Dokumenty, książki i obrazy mają podgląd w ten sam sposób, wewnątrz sejfu.",
  "vt_vsize_ic": "ROZMIAR SEJFU",
  "vt_vsize_h": "Tak duży jak jego dysk",
  "vt_vsize": "Nie ma naszego limitu. Sejf mieści jeden plik albo kilka TB rozłożonych na tysiące plików. Kończy się tam, gdzie kończy się dysk.",
  "vt_fsize_ic": "ROZMIAR PLIKU",
  "vt_fsize_h": "Tyle, ile pozwala dysk",
  "vt_fsize": "16 TB na NTFS, 16 EB na exFAT — i 4 GB na FAT32, bo to limit FAT32, a nie nasz. Szyfrowanie dodaje około 0,09%, więc plik, który ledwo się mieści, przestaje się mieścić: sprawdzenie odbywa się na rozmiarze zaszyfrowanym i odmawia przed rozpoczęciem, z prawdziwą liczbą.",
  "vt_open_ic": "NIE NASZE, BY TRZYMAĆ",
  "vt_open_h": "Format Cryptomatora",
  "vt_open": "Format jest formatem Cryptomatora, odtworzonym z jego publicznej specyfikacji, i działa w obie strony — przetestowane. Sejfy utworzone tutaj otwierają się w Cryptomatorze na Androidzie, iOS, Macu i Linuksie, bez żadnej konwersji. Sejfy, które już masz, też otwierają się tutaj. Gdyby ExplorerFocus zniknął jutro, pliki by nie zniknęły.",
  "vt_yes_h": "Chroni przed",
  "vt_yes": "<li>Każdym, kto skopiuje folder albo dysk — synchronizacja z chmurą, zgubiony pendrive, kopia zapasowa w cudzych rękach</li><li>Każdym, kto ukradnie wyłączony komputer</li><li>Każdym, kto ma dostęp do odczytu dysku, bez hasła</li>",
  "vt_no_h": "Nie chroni przed",
  "vt_no": "<li>Złośliwym oprogramowaniem działającym na twoim koncie <strong>przy otwartym sejfie</strong> — czyta odszyfrowane pliki, jak każdy inny program</li><li>Keyloggerami albo kimś, kto usiądzie przy twoim odblokowanym komputerze z otwartym sejfem</li><li>Kopiami pliku, które istniały jawnie, zanim trafił do środka</li><li>Kimś, kto <strong>zapisuje</strong> na dysku przy zamkniętym sejfie: nie zmieni zawartości — uwierzytelnianie to wykryje — ale może usuwać pliki</li>",
  "vt_honest": "<strong>Dlaczego istnieje ta druga kolumna:</strong> obiecywanie większego bezpieczeństwa, niż się ma, to najgorsze, co może zrobić taka funkcja. Każdy produkt w tej kategorii mógłby opublikować taką listę. Prawie żaden tego nie robi.",
  "vt_paths": "<strong>Efekt uboczny, który warto znać:</strong> każdy zaszyfrowany folder leży na dysku na tej samej, płytkiej głębokości, więc folder zagnieżdżony na dwadzieścia poziomów to wciąż ścieżka z czterech części. Ścieżki, których Eksplorator plików Windows odmawia otwarcia, działają wewnątrz sejfu.",
  "vt_premium": "<a class=\"prem-word\" href=\"#premium\">PREMIUM</a> — tworzenie sejfów. Otwieranie ich jest darmowe, także sejfów utworzonych gdzie indziej.",
  "st_crypto_ic": "SZYFROWANIE",
  "st_crypto": "scrypt, AES-SIV i AES Key Wrap, z Bouncy Castle (MIT) — publiczne i szeroko używane od ponad dwudziestu lat.",
  "st_letter_ic": "LITERA",
  "st_letter": "Dokany (LGPL v3) nie jest dystrybuowany: instalujesz go sam, a eksplorator używa go tylko wtedy, gdy go znajdzie. Most .NET, DokanNet (MIT), podróżuje za to wewnątrz pliku wykonywalnego.",
  "st_format_ic": "FORMAT",
  "st_format": "Format sejfu to format Cryptomatora, odtworzony z jego publicznej specyfikacji. Klucz odzyskiwania korzysta z listy słów BIP-39 (MIT).",
